def f(I, mode='std'):
    H,W=len(I),len(I[0]); O=[r[:] for r in I]
    dots=[(i,j,I[i][j]) for i in range(H) for j in range(W) if I[i][j]]
    def draw_rays():
        for r,c,v in dots:
            if v==1:
                for j in (c+1,c+2):
                    if 0<=j<W: O[r][j]=5
                if r-1>=0: O[r-1][c+2]=1
            elif v==2:
                for j in range(c-1,0,-1):
                    if 0<=j<W: O[r][j]=5
                if c-1>=0: O[r][c-1]=2
            elif v==3:
                for i in range(r+1,r+4):
                    if 0<=i<H: O[i][c]=5
                if 0<=r+3<H: O[r+3][c]=3
            elif v==6:
                for i in range(0,r):
                    if 0<=i<H: O[i][c]=5
                if r-1>=0: O[0][c]=6
    draw_rays()
    # crossings between horizontal-ray (2) and vertical-ray (6): 4 + anti-diagonal tail
    two=[(r,c) for r,c,v in dots if v==2]
    six=[(r,c) for r,c,v in dots if v==6]
    for (r2,c2) in two:
        for (r6,c6) in six:
            if r2<r6 and 1<=c2<c6 and 0<=c2<W:
                O[r2][c6]=4
                for step in range(1,H+W):
                    ii,jj=r2+step,c6-step
                    if ii>H-1 or jj<0: break
                    O[ii][jj]=4
    return O
